from ail import integer_decode, read_bytes, write_stdout_bytes
import sys

# Comparison profile: positive signed int64 CLI counts; ASCII decimal digits only.
def row_positive_token(text: str) -> str:
    if len(text) == 0:
        raise ValueError
    for c in text:
        digit = ord(c) - 48
        if digit < 0 or digit > 9:
            raise ValueError
    token = text.lstrip('0')
    if len(token) == 0 or len(token) > 19:
        raise ValueError
    if len(token) == 19 and token > '9223372036854775807':
        raise ValueError
    return token

def row_report(values: list[int], cols: int) -> str:
    if cols <= 0 or len(values) % cols != 0:
        raise ValueError
    lines: list[str] = []
    total: int = 0
    column: int = 0
    for value in values:
        if value > 0 and total > 9223372036854775807 - value:
            raise ValueError
        if value < 0 and total < -9223372036854775808 - value:
            raise ValueError
        total += value
        column += 1
        if column == cols:
            lines.append(str(total) + '\n')
            total = 0
            column = 0
    return ''.join(lines)

def main() -> int:
    if len(sys.argv) != 4:
        return 2
    try:
        cols_token = row_positive_token(sys.argv[2])
        repeat_token = row_positive_token(sys.argv[3])
        data = read_bytes(sys.argv[1])
        if len(data) % 8 != 0:
            return 2
        values = integer_decode(data, 8, 0)
        if len(values) == 0:
            return 0
        cols = int(cols_token)
        report = row_report(values, cols).encode()
        repeat = int(repeat_token)
        for item in range(repeat):
            write_stdout_bytes(report)
        return 0
    except ValueError:
        return 2
    except OSError:
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
